func checkSubTree(t1 *TreeNode, t2 *TreeNode) bool {
	var same func(a, b *TreeNode) bool
	same = func(a, b *TreeNode) bool {
		if a == nil && b == nil {
			return true
		}
		if a == nil || b == nil {
			return false
		}
		return a.Val == b.Val && same(a.Left, b.Left) && same(a.Right, b.Right)
	}
	if t2 == nil {
		return true
	}
	if t1 == nil {
		return false
	}
	return same(t1, t2) || checkSubTree(t1.Left, t2) || checkSubTree(t1.Right, t2)
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private boolean same(TreeNode a, TreeNode b) {
    if (a == null && b == null) return true;
    if (a == null || b == null) return false;
    return a.val == b.val && same(a.left, b.left) && same(a.right, b.right);
  }

  public boolean checkSubTree(TreeNode t1, TreeNode t2) {
    if (t2 == null) return true;
    if (t1 == null) return false;
    return same(t1, t2) || checkSubTree(t1.left, t2) || checkSubTree(t1.right, t2);
  }
}

class Solution:
    def checkSubTree(self, t1: Optional[TreeNode], t2: Optional[TreeNode]) -> bool:
        def same(a, b):
            if a is None and b is None:
                return True
            if a is None or b is None:
                return False
            return a.val == b.val and same(a.left, b.left) and same(a.right, b.right)

        if t2 is None:
            return True
        if t1 is None:
            return False
        return same(t1, t2) or self.checkSubTree(t1.left, t2) or self.checkSubTree(t1.right, t2)

impl Solution {
  pub fn check_sub_tree(t1: &Option<Box<TreeNode>>, t2: &Option<Box<TreeNode>>) -> bool {
    fn same(a: &Option<Box<TreeNode>>, b: &Option<Box<TreeNode>>) -> bool {
      match (a, b) {
        (None, None) => true,
        (Some(x), Some(y)) => {
          x.val == y.val && same(&x.left, &y.left) && same(&x.right, &y.right)
        }
        _ => false,
      }
    }
    if t2.is_none() {
      return true;
    }
    if t1.is_none() {
      return false;
    }
    same(t1, t2)
      || Solution::check_sub_tree(&t1.as_ref().unwrap().left, t2)
      || Solution::check_sub_tree(&t1.as_ref().unwrap().right, t2)
  }
}

const checkSubTree = (t1: TreeNode | null, t2: TreeNode | null): boolean => {
  const same = (a: TreeNode | null, b: TreeNode | null): boolean => {
    if (!a && !b) return true;
    if (!a || !b) return false;
    return a.val === b.val && same(a.left, b.left) && same(a.right, b.right);
  };
  if (!t2) return true;
  if (!t1) return false;
  return same(t1, t2) || checkSubTree(t1.left, t2) || checkSubTree(t1.right, t2);
};
